    private void startSimThread() {
        motor_id_33.getSimState().Orientation = ChassisReference.CounterClockwise_Positive;
        motor_id_33.getSimState().setMotorType(TalonFXSimState.MotorType.KrakenX60);
        motor_id_34.getSimState().Orientation = ChassisReference.CounterClockwise_Positive;
        motor_id_34.getSimState().setMotorType(TalonFXSimState.MotorType.KrakenX60);

        lastSimTime = Utils.getCurrentTimeSeconds();

        /* Run simulation at a faster rate so PID gains behave more reasonably */
        simNotifier = new Notifier(() -> {
            /* Calculate the time delta */
            final double currentTime = Utils.getCurrentTimeSeconds();
            final double deltaTime = currentTime - lastSimTime;
            lastSimTime = currentTime;

            final var motor_id_33Sim = motor_id_33.getSimState();
            final var motor_id_34Sim = motor_id_34.getSimState();

            /* First set the supply voltage of all the devices */
            motor_id_33Sim.setSupplyVoltage(RobotController.getBatteryVoltage());
            motor_id_34Sim.setSupplyVoltage(RobotController.getBatteryVoltage());

            /* Then calculate the new position and velocity of the simulated elevator */
            var motor_id_33Sim_MotorVoltage = motor_id_33Sim.getMotorVoltage();
            var motor_id_34Sim_MotorVoltage = motor_id_34Sim.getMotorVoltage();
            {
                final var elevatorPosDiff = elevatorSim_motor_id_33.getPositionMeters() -
                    elevatorSim_motor_id_34.getPositionMeters();
                final var simMotorVoltageDiff = motor_id_33Sim_MotorVoltage - motor_id_34Sim_MotorVoltage;
                if (
                    (elevatorPosDiff > 0.08 && simMotorVoltageDiff > 0.0) ||
                    (elevatorPosDiff < -0.08 && simMotorVoltageDiff < 0.0)
                ) {
                    /* One motor is >8 cm higher than the other and driving further away,
                     * elevator cannot tilt any further, use average motor voltage */
                    final var avgSimMotorVoltage = (motor_id_33Sim_MotorVoltage + motor_id_34Sim_MotorVoltage) / 2.0;
                    motor_id_33Sim_MotorVoltage = avgSimMotorVoltage;
                    motor_id_34Sim_MotorVoltage = avgSimMotorVoltage;
                }
            }

            elevatorSim_motor_id_33.setInputVoltage(motor_id_33Sim_MotorVoltage);
            elevatorSim_motor_id_34.setInputVoltage(motor_id_34Sim_MotorVoltage);
            elevatorSim_motor_id_33.update(deltaTime);
            elevatorSim_motor_id_34.update(deltaTime);

            /* Apply the new rotor position and velocity to the motors (before gear ratio) */
            motor_id_33Sim.setRawRotorPosition(
                Radians.of(elevatorSim_motor_id_33.getPositionMeters() / kDrumRadius.in(Meters) * kGearRatio)
            );
            motor_id_33Sim.setRotorVelocity(
                RadiansPerSecond.of(elevatorSim_motor_id_33.getVelocityMetersPerSecond() / kDrumRadius.in(Meters) * kGearRatio)
            );
            motor_id_34Sim.setRawRotorPosition(
                Radians.of(elevatorSim_motor_id_34.getPositionMeters() / kDrumRadius.in(Meters) * kGearRatio)
            );
            motor_id_34Sim.setRotorVelocity(
                RadiansPerSecond.of(elevatorSim_motor_id_34.getVelocityMetersPerSecond() / kDrumRadius.in(Meters) * kGearRatio)
            );
        });
        simNotifier.startPeriodic(kSimLoopPeriod);
    }

